// Applied rules: [III④, C3, C1]
// Skipped rules: []
#[inline(always)]
unsafe fn ReadCommandInternal(
    mut safe: c_int,
    mut s: *mut BrotliDecoderStateInternal,
    mut br: *mut BrotliBitReader,
    mut insert_length: *mut c_int,
) -> c_int {
    let mut cmd_code: uint64_t = 0;
    let mut insert_len_extra: uint64_t = 0 as uint64_t;
    let mut copy_length: uint64_t = 0;
    let mut v: CmdLutElement = CmdLutElement {
        insert_len_extra_bits: 0,
        copy_len_extra_bits: 0,
        distance_code: 0,
        context: 0,
        insert_len_offset: 0,
        copy_len_offset: 0,
    };
    let mut memento: BrotliBitReaderState = BrotliBitReaderState {
        val_: 0,
        bit_pos_: 0,
        next_in: ::core::ptr::null::<uint8_t>(),
        avail_in: 0,
    };

    let htree_command = (*s).htree_command;
    if safe == 0 {
        cmd_code = ReadSymbol(htree_command, br);
    } else {
        BrotliBitReaderSaveState(br, &raw mut memento);
        if SafeReadSymbol(htree_command, br, &raw mut cmd_code) == 0 {
            return BROTLI_FALSE;
        }
    }

    // SAFETY: `cmd_code` comes from the command Huffman alphabet decoder, whose
    // contract guarantees a valid command code index into `kCmdLut`.
    v = unsafe { *kCmdLut.get_unchecked(cmd_code as usize) };

    let distance_code = v.distance_code as c_int;
    let distance_context = v.context as c_int;
    (*s).distance_code = distance_code;
    (*s).distance_context = distance_context;

    let dist_context_map_slice = (*s).dist_context_map_slice;
    // SAFETY: `dist_context_map_slice` points to the decoder state's distance
    // context map, and `distance_context` is the command LUT-provided context
    // used to index that map. This is a single proven unchecked access, with no
    // new runtime check added.
    let dist_htree_index = unsafe { *dist_context_map_slice.offset(distance_context as isize) };
    (*s).dist_htree_index = dist_htree_index;

    *insert_length = v.insert_len_offset as c_int;
    if safe == 0 {
        if (v.insert_len_extra_bits as c_int != 0 as c_int) as c_int as c_long != 0 {
            insert_len_extra = BrotliReadBits24(br, v.insert_len_extra_bits as uint64_t);
        }
        copy_length = BrotliReadBits24(br, v.copy_len_extra_bits as uint64_t);
    } else if SafeReadBits(
        br,
        v.insert_len_extra_bits as uint64_t,
        &raw mut insert_len_extra,
    ) == 0
        || SafeReadBits(br, v.copy_len_extra_bits as uint64_t, &raw mut copy_length) == 0
    {
        BrotliBitReaderRestoreState(br, &raw mut memento);
        return BROTLI_FALSE;
    }

    let copy_len_offset = v.copy_len_offset as c_int;
    (*s).copy_length = copy_length as c_int + copy_len_offset;

    let block_length = &raw mut (*s).block_length;
    // SAFETY: index 1 is a fixed in-bounds slot of the decoder state's
    // `block_length` array; this removes the source-level bounds check only.
    unsafe {
        (*block_length)[1usize] = (*block_length)[1usize].wrapping_sub(1);
    }

    *insert_length += insert_len_extra as c_int;
    return BROTLI_TRUE;
}

